using MediatR;using Namaa.Application.Abstractions.Authentication;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Common.Errors;using Namaa.Application.Quotations.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;using Namaa.Domain.Entities;
namespace Namaa.Application.Quotations.Commands.CreateQuotation;
public sealed class CreateQuotationCommandHandler(IQuotationRepository repository,ICustomerRepository customers,IUserRepository users,ICurrentUser currentUser,IApplicationDbContext db):IRequestHandler<CreateQuotationCommand,Result<QuotationDto>>{public async Task<Result<QuotationDto>>Handle(CreateQuotationCommand request,CancellationToken cancellationToken){if(!currentUser.IsAuthenticated||currentUser.UserId is not long actorUserId)return Result.Failure<QuotationDto>(ApplicationErrors.Unauthenticated);if(await repository.ExistsByNumberAsync(request.QuotationNumber,cancellationToken))return Result.Failure<QuotationDto>(QuotationErrors.DuplicateNumber);if(await customers.FindByIdAsync(request.CustomerId,cancellationToken)is null)return Result.Failure<QuotationDto>(QuotationErrors.CustomerNotFound);if(!await users.ExistsByIdAsync(actorUserId,cancellationToken))return Result.Failure<QuotationDto>(QuotationErrors.UserNotFound);var e=Quotation.Create(request.CustomerId,request.QuotationNumber,request.Title,request.IssueDate,actorUserId,request.ValidUntil,request.Notes,request.Terms);await repository.AddAsync(e,cancellationToken);await db.SaveChangesAsync(cancellationToken);return Result.Success(QuotationDto.FromEntity(e));}}

